import { MAX_PLAYER_LEVEL, type PlayerProgression } from './types';

// Cumulative XP. A smooth quadratic curve keeps early unlocks quick while
// making the final cosmetic tiers meaningful long-term goals.
export function xpForLevel(level: number): number {
  const safeLevel = Math.max(1, Math.min(MAX_PLAYER_LEVEL, Math.floor(level)));
  const n = safeLevel - 1;
  return 100 * n * n + 400 * n;
}

export const MAX_PLAYER_XP = xpForLevel(MAX_PLAYER_LEVEL);

export function levelForXp(xp: number): number {
  const safeXp = Math.max(0, Math.min(MAX_PLAYER_XP, Math.floor(xp)));
  let low = 1;
  let high = MAX_PLAYER_LEVEL;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (xpForLevel(mid) <= safeXp) low = mid;
    else high = mid - 1;
  }
  return low;
}

export function createProgression(xp = 0): PlayerProgression {
  const safeXp = Math.max(0, Math.min(MAX_PLAYER_XP, Math.floor(xp)));
  return { xp: safeXp, level: levelForXp(safeXp) };
}

export function addXp(progression: PlayerProgression, amount: number): PlayerProgression {
  if (!Number.isFinite(amount) || amount <= 0) return createProgression(progression.xp);
  return createProgression(progression.xp + Math.floor(amount));
}

export function xpProgressWithinLevel(progression: PlayerProgression): {
  current: number;
  required: number;
  ratio: number;
} {
  const normalized = createProgression(progression.xp);
  if (normalized.level >= MAX_PLAYER_LEVEL) return { current: 0, required: 0, ratio: 1 };
  const floor = xpForLevel(normalized.level);
  const ceiling = xpForLevel(normalized.level + 1);
  return {
    current: normalized.xp - floor,
    required: ceiling - floor,
    ratio: (normalized.xp - floor) / (ceiling - floor),
  };
}
