import type { PlayerCosmetics, PlayerProfile, PlayerSettings, PlayerStatistics } from './types';
import { createProgression } from './progression';

export function createDefaultCosmetics(): PlayerCosmetics {
  return {
    ballId: 'classic-white', trailId: 'none', hatId: null,
    unlockedBallIds: ['classic-white'], unlockedTrailIds: ['none'], unlockedHatIds: [],
  };
}

export function createDefaultStatistics(): PlayerStatistics {
  return {
    matchesPlayed: 0, matchesWon: 0, holesPlayed: 0, holesCompleted: 0,
    totalStrokes: 0, holesInOne: 0, bestRoundStrokes: null, totalPlayTimeSeconds: 0,
  };
}

export function createDefaultSettings(): PlayerSettings {
  return {
    controlScheme: 'drag', masterVolume: 0.8, musicVolume: 0.65, effectsVolume: 0.8,
    cameraSensitivity: 1, invertCameraY: false, qualityPreset: 'high', reducedMotion: false,
  };
}

function fallbackId(): string {
  return `local-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

export function createDefaultProfile(now = new Date(), id?: string): PlayerProfile {
  const timestamp = now.toISOString();
  const generatedId = id ?? globalThis.crypto?.randomUUID?.() ?? fallbackId();
  return {
    id: generatedId,
    displayName: 'Player',
    createdAt: timestamp,
    updatedAt: timestamp,
    progression: createProgression(),
    cosmetics: createDefaultCosmetics(),
    statistics: createDefaultStatistics(),
    settings: createDefaultSettings(),
  };
}
