import { addXp } from './progression';
import type { PlayerProfile, PlayerSettings, PlayerStatistics } from './types';

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

export function awardPlayerXp(profile: PlayerProfile, xp: number, now = new Date()): PlayerProfile {
  return { ...profile, progression: addXp(profile.progression, xp), updatedAt: now.toISOString() };
}

export function updatePlayerSettings(
  profile: PlayerProfile,
  patch: Partial<PlayerSettings>,
  now = new Date(),
): PlayerProfile {
  const settings = { ...profile.settings, ...patch };
  settings.masterVolume = clamp01(settings.masterVolume);
  settings.musicVolume = clamp01(settings.musicVolume);
  settings.effectsVolume = clamp01(settings.effectsVolume);
  settings.cameraSensitivity = Math.max(0.1, Math.min(3, settings.cameraSensitivity));
  return { ...profile, settings, updatedAt: now.toISOString() };
}

export function recordStatistics(
  profile: PlayerProfile,
  patch: Partial<PlayerStatistics>,
  now = new Date(),
): PlayerProfile {
  const statistics = { ...profile.statistics, ...patch };
  for (const key of ['matchesPlayed','matchesWon','holesPlayed','holesCompleted','totalStrokes','holesInOne','totalPlayTimeSeconds'] as const) {
    statistics[key] = Math.max(0, Math.floor(Number.isFinite(statistics[key]) ? statistics[key] : 0));
  }
  if (statistics.bestRoundStrokes !== null) statistics.bestRoundStrokes = Math.max(0, Math.floor(statistics.bestRoundStrokes));
  return { ...profile, statistics, updatedAt: now.toISOString() };
}
