import { createDefaultCosmetics, createDefaultProfile, createDefaultSettings, createDefaultStatistics } from '../player/defaults';
import { createProgression } from '../player/progression';
import type { PlayerProfile } from '../player/types';

export const SAVE_VERSION = 2;
export const DEFAULT_SAVE_KEY = 'crazy-putt-arena.save';

export interface SaveEnvelope {
  version: typeof SAVE_VERSION;
  profile: PlayerProfile;
}

export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

type UnknownRecord = Record<string, unknown>;
const isRecord = (value: unknown): value is UnknownRecord => typeof value === 'object' && value !== null && !Array.isArray(value);
const stringValue = (value: unknown, fallback: string) => typeof value === 'string' && value.length > 0 ? value : fallback;
const numberValue = (value: unknown, fallback: number) => typeof value === 'number' && Number.isFinite(value) ? value : fallback;
const booleanValue = (value: unknown, fallback: boolean) => typeof value === 'boolean' ? value : fallback;
const stringArray = (value: unknown, fallback: string[]) => Array.isArray(value) && value.every(v => typeof v === 'string') ? [...new Set(value)] : fallback;

function normalizeProfile(value: unknown, fallback: PlayerProfile): PlayerProfile {
  if (!isRecord(value)) return fallback;
  const progression = isRecord(value.progression) ? value.progression : {};
  const cosmetics = isRecord(value.cosmetics) ? value.cosmetics : {};
  const statistics = isRecord(value.statistics) ? value.statistics : {};
  const settings = isRecord(value.settings) ? value.settings : {};
  const defaultCosmetics = createDefaultCosmetics();
  const defaultStats = createDefaultStatistics();
  const defaultSettings = createDefaultSettings();
  const normalizedCosmetics = {
    ballId: stringValue(cosmetics.ballId, defaultCosmetics.ballId),
    trailId: stringValue(cosmetics.trailId, defaultCosmetics.trailId),
    hatId: typeof cosmetics.hatId === 'string' ? cosmetics.hatId : null,
    unlockedBallIds: stringArray(cosmetics.unlockedBallIds, defaultCosmetics.unlockedBallIds),
    unlockedTrailIds: stringArray(cosmetics.unlockedTrailIds, defaultCosmetics.unlockedTrailIds),
    unlockedHatIds: stringArray(cosmetics.unlockedHatIds, defaultCosmetics.unlockedHatIds),
  };
  if (!normalizedCosmetics.unlockedBallIds.includes(normalizedCosmetics.ballId)) normalizedCosmetics.ballId = defaultCosmetics.ballId;
  if (!normalizedCosmetics.unlockedTrailIds.includes(normalizedCosmetics.trailId)) normalizedCosmetics.trailId = defaultCosmetics.trailId;
  if (normalizedCosmetics.hatId && !normalizedCosmetics.unlockedHatIds.includes(normalizedCosmetics.hatId)) normalizedCosmetics.hatId = null;
  return {
    id: stringValue(value.id, fallback.id),
    displayName: stringValue(value.displayName, fallback.displayName).slice(0, 32),
    createdAt: stringValue(value.createdAt, fallback.createdAt),
    updatedAt: stringValue(value.updatedAt, fallback.updatedAt),
    progression: createProgression(numberValue(progression.xp, 0)),
    cosmetics: normalizedCosmetics,
    statistics: {
      matchesPlayed: Math.max(0, Math.floor(numberValue(statistics.matchesPlayed, defaultStats.matchesPlayed))),
      matchesWon: Math.max(0, Math.floor(numberValue(statistics.matchesWon, defaultStats.matchesWon))),
      holesPlayed: Math.max(0, Math.floor(numberValue(statistics.holesPlayed, defaultStats.holesPlayed))),
      holesCompleted: Math.max(0, Math.floor(numberValue(statistics.holesCompleted, defaultStats.holesCompleted))),
      totalStrokes: Math.max(0, Math.floor(numberValue(statistics.totalStrokes, defaultStats.totalStrokes))),
      holesInOne: Math.max(0, Math.floor(numberValue(statistics.holesInOne, defaultStats.holesInOne))),
      bestRoundStrokes: statistics.bestRoundStrokes === null ? null : Math.max(0, Math.floor(numberValue(statistics.bestRoundStrokes, 0))),
      totalPlayTimeSeconds: Math.max(0, Math.floor(numberValue(statistics.totalPlayTimeSeconds, defaultStats.totalPlayTimeSeconds))),
    },
    settings: {
      controlScheme: settings.controlScheme === 'charge' ? 'charge' : 'drag',
      masterVolume: Math.max(0, Math.min(1, numberValue(settings.masterVolume, defaultSettings.masterVolume))),
      musicVolume: Math.max(0, Math.min(1, numberValue(settings.musicVolume, defaultSettings.musicVolume))),
      effectsVolume: Math.max(0, Math.min(1, numberValue(settings.effectsVolume, defaultSettings.effectsVolume))),
      cameraSensitivity: Math.max(0.1, Math.min(3, numberValue(settings.cameraSensitivity, defaultSettings.cameraSensitivity))),
      invertCameraY: booleanValue(settings.invertCameraY, defaultSettings.invertCameraY),
      qualityPreset: settings.qualityPreset === 'low' || settings.qualityPreset === 'medium' ? settings.qualityPreset : 'high',
      reducedMotion: booleanValue(settings.reducedMotion, defaultSettings.reducedMotion),
    },
  };
}

// v1 used flat xp and older names for the two control modes.
function migrateV1(raw: UnknownRecord, fallback: PlayerProfile): PlayerProfile {
  const source = isRecord(raw.profile) ? raw.profile : raw;
  const migrated: UnknownRecord = { ...source };
  migrated.progression = { xp: numberValue(source.xp, isRecord(source.progression) ? numberValue(source.progression.xp, 0) : 0) };
  if (isRecord(source.settings)) {
    migrated.settings = { ...source.settings, controlScheme: source.settings.controlScheme === 'hold' ? 'charge' : 'drag' };
  }
  return normalizeProfile(migrated, fallback);
}

export function migrateSave(raw: unknown, fallback = createDefaultProfile()): SaveEnvelope {
  if (!isRecord(raw)) return { version: SAVE_VERSION, profile: fallback };
  const version = numberValue(raw.version, 1);
  if (version === 1) return { version: SAVE_VERSION, profile: migrateV1(raw, fallback) };
  if (version === SAVE_VERSION) return { version: SAVE_VERSION, profile: normalizeProfile(raw.profile, fallback) };
  // Future saves must not be destructively interpreted by an older client.
  return { version: SAVE_VERSION, profile: fallback };
}

export class SaveManager {
  constructor(
    private readonly storage: StorageLike | null = typeof localStorage === 'undefined' ? null : localStorage,
    private readonly key = DEFAULT_SAVE_KEY,
  ) {}

  load(): PlayerProfile {
    const fallback = createDefaultProfile();
    if (!this.storage) return fallback;
    try {
      const serialized = this.storage.getItem(this.key);
      if (!serialized) return fallback;
      return migrateSave(JSON.parse(serialized), fallback).profile;
    } catch {
      return fallback;
    }
  }

  save(profile: PlayerProfile): boolean {
    if (!this.storage) return false;
    try {
      const fallback = createDefaultProfile(new Date(), profile.id);
      const envelope: SaveEnvelope = { version: SAVE_VERSION, profile: normalizeProfile(profile, fallback) };
      this.storage.setItem(this.key, JSON.stringify(envelope));
      return true;
    } catch {
      return false;
    }
  }

  reset(): PlayerProfile {
    try { this.storage?.removeItem(this.key); } catch { /* storage may be unavailable */ }
    return createDefaultProfile();
  }
}
EOF

